const express = require('express');
const router = express.Router();
const admin = require('firebase-admin');
const { db } = require('../db');

router.post('/api/devices/fcm-token', verifyAuthToken, async (req, res) => {
  const { fcmToken, devicePlatform } = req.body;
  const targetUserId = req.user.id;

  await db.query(
    'INSERT INTO user_push_devices (user_id, token, platform, registered_at) VALUES ($1, $2, $3, NOW()) ON CONFLICT (token) DO UPDATE SET user_id = $1, registered_at = NOW()',
    [targetUserId, fcmToken, devicePlatform]
  );

  return res.json({ success: true, registeredUser: targetUserId });
});
